mapper.select:
SELECT COUNT(*)
FROM member_task_completion
WHERE company_id = #{companyId}
  AND task_id = #{taskId}
  AND voided = 0

SELECT COUNT(DISTINCT user_id)
FROM member_task_completion
WHERE company_id = #{companyId}
  AND task_id = #{taskId}
  AND voided = 0

SELECT g.status AS status, COUNT(*) AS cnt
FROM member_task_reward_grant g
INNER JOIN member_task_completion c ON c.completion_id = g.completion_id AND c.voided = 0
WHERE g.company_id = #{companyId}
  AND g.task_id = #{taskId}
GROUP BY g.status

SELECT COALESCE(SUM(CAST(o.total_fee AS SIGNED)), 0)
FROM orders_normal_orders o
WHERE o.company_id = #{companyId}
  AND o.member_task_id = #{taskId}
  AND o.pay_status = 'PAYED'
  AND o.order_status <> 'CANCEL'

SELECT COUNT(DISTINCT c.invitee_user_id)
FROM member_task_completion c
WHERE c.company_id = #{companyId}
  AND c.task_id = #{taskId}
  AND c.voided = 0
  AND c.invitee_user_id > 0
